package com.pharmacy.controller;
import com.pharmacy.common.PageData;import com.pharmacy.exception.GlobalExceptionHandler;import com.pharmacy.service.PublicMedicineService;import org.junit.jupiter.api.*;import org.springframework.test.web.servlet.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import java.util.List;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class PublicMedicineControllerTest {private PublicMedicineService service;private MockMvc mvc;@BeforeEach void setup(){service=mock(PublicMedicineService.class);mvc=MockMvcBuilders.standaloneSetup(new PublicMedicineController(service)).setControllerAdvice(new GlobalExceptionHandler()).build();}@Test void categories()throws Exception{when(service.listEnabledCategories()).thenReturn(List.of());mvc.perform(get("/api/public/categories")).andExpect(status().isOk()).andExpect(jsonPath("$.code").value(0));}@Test void page()throws Exception{when(service.pageMedicines(anyLong(),anyLong(),any(),any(),any())).thenReturn(new PageData<>(List.of(),0,1,12,0));mvc.perform(get("/api/public/medicines")).andExpect(status().isOk());verify(service).pageMedicines(1,12,null,null,"default");}@Test void detail()throws Exception{mvc.perform(get("/api/public/medicines/9")).andExpect(status().isOk());verify(service).getMedicine(9L);}}
